  "preconditions": [
    {
      "id": "P1",
      "expression": "1 <= A <= 20",
      "description": "The width of the picture is between 1 and 20."
    },
    {
      "id": "P2",
      "expression": "1 <= B <= 20",
      "description": "The height of the picture is between 1 and 20."
    },
    {
      "id": "P3",
      "expression": "A and B are divisible by X and Y respectively",
