    {
      "id": "Q1",
      "expression": "output_number_of_puzzles > 0",
      "description": "The number of good puzzles is positive."
    },
    {
      "id": "Q2",
      "expression": "1 <= minimal_piece_width <= A",
      "description": "The minimal piece width is between 1 and the width of the picture."
    },
    {
      "id": "Q3",
      "expression": "1 <= minimal_piece_height <= B",
      "description": "The minimal piece height is between 1 and the height of the picture."
    },
    {
      "id": "Q4",
      "expression": "minimal_piece_width * minimal_piece_height <= A * B",
      "description": "The area of the smallest piece is less than or equal to the area of the whole picture."
    },
    {
      "id": "Q5",
      "expression": "all(X * Y <= A * B for X, Y in good_puzzles)",
      "description": "All good puzzles have sizes that are possible given the picture dimensions."
    },
    {
      "id": "Q6",
      "expression": "all(X * Y == minimal_piece_width * minimal_piece_height for X, Y in good_puzzles if X * Y == minimal_piece_width * minimal_piece_height)",
      "description": "The smallest area among all good puzzles is the area of the smallest piece."
    },
    {
      "id": "Q7",
      "expression": "all(X * Y == minimal_piece_width * minimal_piece_height and (X <= minimal_piece_width or (X == minimal_piece_width and Y < minimal_piece_height)) for X, Y in good_puzzles if X * Y == minimal_piece_width * minimal_piece_height)",
      "description": "If there are multiple pieces with the same area, the one with the smaller width is chosen."
    }
  ],
  "invariants": []
}
